class Widget {};

void demonstrate_shared_ptr_pitfall() {
    Widget* raw_ptr = new Widget; // A raw pointer to a resource.

    // DANGEROUS: Each construction from the raw pointer creates a NEW control block.
    // sptr1 creates the first control block for raw_ptr.
    std::shared_ptr<Widget> sptr1(raw_ptr);

    // sptr2 is constructed from the SAME raw pointer. It has NO KNOWLEDGE
    // of sptr1 and creates a SECOND, independent control block.
    // This guarantees a double-delete and is undefined behavior.
    std::shared_ptr<Widget> sptr2(raw_ptr); // VERY BAD!

    // sptr1 and sptr2 will both try to delete raw_ptr when they go out of scope.
}

void demonstrate_shared_ptr_correctness() {
    // CORRECT: Create one shared_ptr, then share it via copy construction.
    std::shared_ptr<Widget> sptr1(new Widget);

    // sptr2 is copy-constructed. It shares ownership and points to the
    // SAME control block used by sptr1. The reference count is incremented.
    std::shared_ptr<Widget> sptr2 = sptr1; // Correct and safe.

    // Now, the Widget is deleted only once, when the last shared_ptr is destroyed.
}
